import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Span, Turn } from '../types'
import {
  MAX_TURNS,
  addSpan,
  breakdown,
  closeSpans,
  describeCall,
  fmtMs,
  insights,
  patchSpan,
  percentages,
  report,
  ruleText,
  sparkline,
  toTrace,
} from './model'
import { BandView, Empty, Legendary, PaneFoot, PaneHead, WaterfallText, waterfallSvg } from './views'

const PANE = 'turn-profiler'
const TOOL = 'turn_profile'
const MODEL_TOOL = `mcp__turn-profiler__${TOOL}`

const live = atom({ plugin: 'turn-profiler', key: 'live' } as const, null)
const turns = atom({ plugin: 'turn-profiler', key: 'turns' } as const, [])
const viewing = atom({ plugin: 'turn-profiler', key: 'viewing' } as const, null)
const isBandHidden = atom({ plugin: 'turn-profiler', key: 'isBandHidden' } as const, false)
const tick = atom({ plugin: 'turn-profiler', key: 'tick' } as const, 0)

type Running = { name: string; input: string; askedAt?: number }

/** Milliseconds since the live turn began, or undefined with no turn running. */
async function offset($: EngineInterface): Promise<number | undefined> {
  const turn = await read($, live)
  if (turn === null) return undefined
  return (await $.clock.now()) - turn.startedAt
}

function argsOf(e: object): Record<string, unknown> {
  const { tool, tool_use_id, agentId, consent, requestMeta, ...rest } = e as Record<string, unknown>
  return rest
}

/** A finished span's approval wait: its wall time less what the tool itself ran. */
function withExec(s: Span, execMs: number): Span {
  if (s.end === undefined || !s.isAsked) return { ...s, execMs }
  return { ...s, execMs, waitMs: Math.max(0, s.end - s.start - execMs) }
}

/** The turn the pane shows, its place among the finished ones, and whether it is live. */
async function shown($: EngineInterface) {
  const [now, list, id] = [await read($, live), await read($, turns), await read($, viewing)]
  if (id !== null) {
    const index = list.findIndex(t => t.id === id)
    if (index !== -1) return { turn: list[index]!, index, list, isLive: false }
  }
  if (now !== null) return { turn: now, index: list.length, list, isLive: true }
  return { turn: list[list.length - 1] ?? null, index: list.length - 1, list, isLive: false }
}

// Calls in flight and the execution times PostToolUse reported, for the
// live turn; a reload starts them over, which costs one turn's waits at most.
const running = new Map<string, Running>()
const execs = new Map<string, number>()
let seq = 0

async function copy($: EngineInterface, text: string) {
  const done = await $.ui.copy({ text })
  $.ui.toast(done.isCopied ? `Copied ${text}` : text)
}

async function exportTrace($: EngineInterface): Promise<string> {
  const { turn } = await shown($)
  if (turn === null) return 'No turn to export yet.'
  const now = turn.durationMs ?? (await $.clock.now()) - turn.startedAt
  const home = (await $.env.get('HOME')) ?? '.'
  const stamp = new Date(turn.startedAt).toISOString().replace(/[:.]/g, '-')
  const path = `${home}/.claude/turn-profiler/${stamp}.trace.json`
  try {
    await $.fs.write(path, JSON.stringify(toTrace(turn, now)))
  } catch (err) {
    return `Could not save the trace to ${path}: ${err instanceof Error ? err.message : String(err)}`
  }
  const done = await $.ui.copy({ text: path })
  return `Saved the trace to ${path}${done.isCopied ? ' (path copied)' : ''}. Drop it into https://ui.perfetto.dev to explore it.`
}

async function recordExec($: EngineInterface, id: string, ms: number | undefined) {
  if (ms === undefined) return
  execs.set(id, ms)
  await update($, live, t => t && patchSpan(t, id, s => withExec(s, ms))).catch(() => undefined)
}

/** The model's own window on the profile, so "why was that slow?" has an answer. */
async function answerProfile($: EngineInterface, e: object) {
  const asked = Number(argsOf(e).turns ?? 3)
  const count = Number.isFinite(asked) ? Math.min(10, Math.max(1, Math.floor(asked))) : 3
  const finished = (await read($, turns)).slice(-count)
  const current = await read($, live)
  const sections = finished.length > 0 || current === null ? [report(finished, 0)] : []
  if (current !== null) {
    sections.push(`The turn in progress, so far:\n${report([current], (await $.clock.now()) - current.startedAt)}`)
  }
  const text = sections.join('\n\n')
  return { result: text, text }
}

export const register: Register = (on, options) => {
  const alertMs = Number(options.alertAfterSeconds ?? 60) * 1000
  const bandMinMs = Number(options.bandMinSeconds ?? 10) * 1000

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'profile',
      description: 'Turn profiler: where each turn went (model, tools, approvals)',
      argumentHint: '[export | band | clear]',
    })
    await $.tool.register({
      name: TOOL,
      description:
        "Timing profile of this session's recent turns: how much went to model requests, tool calls and waiting for the user's approval, the slowest calls, and what would make them faster. Use when the user asks why something was slow or how to speed Claude up.",
      inputSchema: {
        type: 'object',
        properties: { turns: { type: 'number', description: 'How many recent turns to report (default 3).' } },
      },
    })
    $.clock.every(1000, () => {
      void read($, live).then(t => (t === null ? undefined : update($, tick, n => n + 1)))
    })
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    running.clear()
    execs.clear()
    const startedAt = await $.clock.now()
    const prompt = e.text.replace(/\s+/g, ' ').trim()
    const turn: Turn = {
      id: e.turnId,
      prompt: prompt === '' ? '(continuation)' : prompt.length > 100 ? `${prompt.slice(0, 99)}…` : prompt,
      startedAt,
      spans: [],
    }
    await update($, live, () => turn)
    await update($, viewing, () => null)
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    const t0 = await offset($).catch(() => undefined)
    if (t0 === undefined) return yield* next(e)

    const id = `m:${e.agentId ?? 'main'}:${e.turnId}:${e.index}`
    const span: Span = {
      id,
      kind: 'model',
      name: e.model,
      detail: `#${e.index + 1}`,
      start: t0,
      ...(e.agentId !== undefined ? { agentId: e.agentId } : {}),
      ...(e.effort !== undefined ? { effort: String(e.effort) } : {}),
    }
    await update($, live, t => t && addSpan(t, span)).catch(() => undefined)

    const stream = next(e)
    let first: number | undefined
    for await (const chunk of stream) {
      if (first === undefined) first = (await offset($).catch(() => undefined)) ?? t0
      yield chunk
    }
    const result = await stream.result
    const t1 = (await offset($).catch(() => undefined)) ?? t0
    await update($, live, t =>
      t && patchSpan(t, id, s => ({
        ...s,
        end: t1,
        ...(first !== undefined ? { firstTokenMs: first - t0 } : {}),
        ...(result.usage ? { outTokens: result.usage.output_tokens } : {}),
      })),
    ).catch(() => undefined)
    return result
  })

  on('tool.call', async ($, e, next) => {
    if (String(e.tool) === MODEL_TOOL) return answerProfile($, e)
    const t0 = await offset($).catch(() => undefined)
    if (t0 === undefined) return next(e)

    const id = e.tool_use_id ?? `t:${++seq}`
    const input = argsOf(e)
    running.set(id, { name: e.tool, input: JSON.stringify(input) })
    const span: Span = {
      id,
      kind: 'tool',
      name: e.tool,
      detail: describeCall(e.tool, input),
      start: t0,
      ...(e.agentId !== undefined ? { agentId: e.agentId } : {}),
    }
    await update($, live, t => t && addSpan(t, span)).catch(() => undefined)

    const ran = await next(e)

    const t1 = (await offset($).catch(() => undefined)) ?? t0
    const call = running.get(id)
    const exec = execs.get(id)
    running.delete(id)
    const isError = ran.deny !== undefined || ran.isError === true
    await update($, live, t =>
      t && patchSpan(t, id, s => {
        const ended: Span = { ...s, end: t1, ...(isError ? { isError: true } : {}) }
        if (exec !== undefined) return withExec(ended, exec)
        if (call?.askedAt !== undefined) return { ...ended, waitMs: Math.max(0, t1 - call.askedAt) }
        return ended
      }),
    ).catch(() => undefined)
    return ran
  }).catch(($, e, next) => next(e))

  on('classic.PermissionRequest', async ($, e, next) => {
    const at = await offset($).catch(() => undefined)
    if (at !== undefined) {
      const input = JSON.stringify(e.tool_input)
      const waiting = [...running].filter(([, r]) => r.name === e.tool_name && r.askedAt === undefined)
      const match = waiting.find(([, r]) => r.input === input) ?? waiting[0]
      if (match !== undefined) {
        const [id, call] = match
        call.askedAt = at
        const suggestion = e.permission_suggestions?.find(
          (u): u is Extract<typeof u, { type: 'addRules' }> => u.type === 'addRules' && u.behavior === 'allow',
        )?.rules[0]
        await update($, live, t =>
          t && patchSpan(t, id, s => ({ ...s, isAsked: true, ...(suggestion ? { rule: ruleText(suggestion) } : {}) })),
        ).catch(() => undefined)
      }
    }
    return next(e)
  })

  on('classic.PostToolUse', async ($, e, next) => {
    await recordExec($, e.tool_use_id, e.duration_ms)
    return next(e)
  })

  on('classic.PostToolUseFailure', async ($, e, next) => {
    await recordExec($, e.tool_use_id, e.duration_ms)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined) return result

    const turn = await read($, live)
    if (turn === null) return result
    const done: Turn = {
      ...closeSpans(turn, e.durationMs),
      durationMs: e.durationMs,
      ...(e.isAborted ? { isAborted: true } : {}),
    }
    const history = await read($, turns)
    await update($, turns, list => [...list, done].slice(-MAX_TURNS))
    await update($, live, () => null)
    running.clear()
    execs.clear()

    if (alertMs > 0 && e.durationMs >= alertMs && !e.isAborted) {
      const p = percentages(breakdown(done, e.durationMs))
      const top = insights(done, history, e.durationMs)[0]
      const line = `Turn done in ${fmtMs(e.durationMs)}: model ${p.model}%, tools ${p.tool}%${p.wait > 0 ? `, approvals ${p.wait}%` : ''}`
      $.ui.toast(top ? `${line}. ${top.text}` : line)
      void $.ui.notify(top ? `${line}. ${top.text}` : line, { title: 'Claude finished' }).catch(() => undefined)
    }
    return result
  })

  on('command.run', { command: 'profile' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'export') return { text: await exportTrace($) }
    if (arg === 'band') {
      const hidden = await update($, isBandHidden, h => !h)
      return { text: hidden ? 'The profiler band is hidden. /profile band shows it again.' : 'The profiler band is shown.' }
    }
    if (arg === 'clear') {
      await update($, turns, () => [])
      await update($, viewing, () => null)
      return { text: "Cleared this session's turn profiles." }
    }
    if (arg !== '') return { text: 'Usage: /profile [export | band | clear]' }
    await $.ui.open({ id: PANE, title: 'Turn profiler' })
    return { text: 'Turn profiler opened.' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || e.props.isWorking || (await read($, isBandHidden))) return next(e)
    const list = await read($, turns)
    const last = list[list.length - 1]
    if (last === undefined || (last.durationMs ?? 0) < bandMinMs) return next(e)

    const now = last.durationMs ?? 0
    const els = $.ui.resolve(e)
    return BandView(els, {
      turn: last,
      breakdown: breakdown(last, now),
      insight: insights(last, list.slice(0, -1), now)[0],
      spark: sparkline(list.slice(-12).map(t => t.durationMs ?? 0)),
      columns: e.props.bodyColumns,
      onOpen: () => void $.ui.open({ id: PANE, title: 'Turn profiler' }),
      onHide: () => void update($, isBandHidden, () => true),
      onCopy: rule => void copy($, rule),
    })
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { turn, index, list, isLive } = await shown($)
    const els = $.ui.resolve(e)
    if (turn === null) return Empty(els)

    if (isLive) await read($, tick)
    const now = turn.durationMs ?? (await $.clock.now()) - turn.startedAt
    const columns = e.props.bodyColumns
    const rows = Math.max(6, (e.viewport?.rows ?? 40) - 18)
    const ids = list.map(t => t.id)
    const go = (id: string | null) => () => void update($, viewing, () => id)
    const data = {
      turn,
      isLive,
      position: { index, count: list.length },
      breakdown: breakdown(turn, now),
      insights: insights(turn, list.slice(0, Math.max(0, index)), now),
      now,
      columns,
      isBandHidden: await read($, isBandHidden),
      onPrev: go(ids[Math.max(0, index - 1)] ?? null),
      onNext: go(index + 1 < ids.length ? ids[index + 1]! : null),
      onLatest: go(null),
      onExport: () => void exportTrace($).then(text => $.ui.toast(text)),
      onToggleBand: () => void update($, isBandHidden, h => !h),
      onCopy: (rule: string) => void copy($, rule),
    }
    const { Box } = els

    if (e.surface === 'terminal') {
      return (
        <Box flexDirection="column" gap={1}>
          {PaneHead(els, data)}
          <Box flexDirection="column">
            {Legendary(els)}
            {WaterfallText(els, turn.spans, now, now, columns, rows)}
          </Box>
          {PaneFoot(els, data)}
        </Box>
      )
    }

    const { Svg } = $.ui.resolve(e)
    const width = Math.max(360, Math.min(1200, Math.round(columns * 7.6)))
    const chart = waterfallSvg(turn.spans, now, now, width, rows + 10)
    return (
      <Box flexDirection="column" gap={1}>
        {PaneHead(els, data)}
        {turn.spans.length > 0 && (
          <Box flexDirection="column">
            {Legendary(els)}
            <Svg
              source={chart.source}
              alt={`Waterfall of ${turn.spans.length} model requests and tool calls over ${fmtMs(now)}`}
              width={width}
              height={chart.height}
              isInteractive
            />
            {chart.hidden > 0 && <els.Text dimColor>+{chart.hidden} shorter spans not drawn</els.Text>}
          </Box>
        )}
        {PaneFoot(els, data)}
      </Box>
    )
  })
}

