import type { Breakdown, Category, Insight, Span, Turn } from '../types'

export const MAX_SPANS = 300
export const MAX_TURNS = 30

const READ_ONLY = new Set(['Read', 'Grep', 'Glob', 'LS', 'NotebookRead'])
const PRIORITY: Record<Category, number> = { other: 0, model: 1, tool: 2, wait: 3 }

export function fmtMs(ms: number): string {
  const n = Math.max(0, Math.round(ms))
  if (n < 1000) return `${n}ms`
  if (n < 9_950) return `${(n / 1000).toFixed(1)}s`
  const seconds = Math.round(n / 1000)
  if (seconds < 60) return `${seconds}s`
  return `${Math.floor(seconds / 60)}m${String(seconds % 60).padStart(2, '0')}s`
}

function oneLine(text: string, max: number): string {
  const flat = text.replace(/\s+/g, ' ').trim()
  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat
}

function tail(path: string): string {
  const parts = path.split('/').filter(Boolean)
  return parts.length > 2 ? `…/${parts.slice(-2).join('/')}` : path
}

/** A one-line description of what a tool call was asked to do. */
export function describeCall(tool: string, input: Readonly<Record<string, unknown>>): string {
  const str = (key: string) => (typeof input[key] === 'string' ? (input[key] as string) : '')
  switch (tool) {
    case 'Bash':
      return oneLine(str('command'), 80)
    case 'Read':
    case 'Write':
    case 'Edit':
    case 'NotebookEdit':
      return tail(str('file_path') || str('notebook_path'))
    case 'Grep':
    case 'Glob':
      return oneLine(str('pattern'), 60)
    case 'WebFetch':
      return oneLine(str('url').replace(/^https?:\/\//, ''), 60)
    case 'WebSearch':
      return oneLine(str('query'), 60)
    case 'Agent':
    case 'Task':
      return oneLine(str('description') || str('subagent_type'), 60)
    default: {
      const first = Object.values(input).find(v => typeof v === 'string')
      return typeof first === 'string' ? oneLine(first, 60) : ''
    }
  }
}

/** `Bash(npm test:*)` from the rule the engine suggested at a permission prompt. */
export function ruleText(rule: { toolName: string; ruleContent?: string }): string {
  return rule.ruleContent ? `${rule.toolName}(${rule.ruleContent})` : rule.toolName
}

export function spanEnd(span: Span, now: number): number {
  return span.end ?? Math.max(span.start, now)
}

/** Closes every span still open at `at`, as a turn that ended does. */
export function closeSpans(turn: Turn, at: number): Turn {
  return {
    ...turn,
    spans: turn.spans.map(s => (s.end === undefined ? { ...s, end: Math.max(s.start, at) } : s)),
  }
}

/** Adds a span, keeping the turn under the cap. */
export function addSpan(turn: Turn, span: Span): Turn {
  if (turn.spans.length >= MAX_SPANS) {
    return { ...turn, droppedSpans: (turn.droppedSpans ?? 0) + 1 }
  }
  return { ...turn, spans: [...turn.spans, span] }
}

export function patchSpan(turn: Turn, id: string, patch: (s: Span) => Span): Turn {
  return { ...turn, spans: turn.spans.map(s => (s.id === id ? patch(s) : s)) }
}

/**
 * Where the main loop's wall clock went, each millisecond counted once:
 * waiting on an approval over a tool running over the model streaming;
 * whatever none covers (hooks, compaction, local work) is `other`.
 */
export function breakdown(turn: Turn, now: number): Breakdown {
  const total = turn.durationMs ?? now
  const parts: { from: number; to: number; cat: Category }[] = []

  for (const s of turn.spans) {
    if (s.agentId !== undefined) continue
    const end = Math.min(spanEnd(s, now), total)
    if (s.kind === 'model') {
      parts.push({ from: s.start, to: end, cat: 'model' })
      continue
    }
    const wait = Math.min(s.waitMs ?? 0, end - s.start)
    if (wait > 0) parts.push({ from: s.start, to: s.start + wait, cat: 'wait' })
    parts.push({ from: s.start + wait, to: end, cat: 'tool' })
  }

  const edges = [...new Set([0, total, ...parts.flatMap(p => [p.from, p.to])])]
    .filter(t => t >= 0 && t <= total)
    .sort((a, b) => a - b)
  const out: Breakdown = { model: 0, tool: 0, wait: 0, other: 0 }

  for (let i = 0; i < edges.length - 1; i++) {
    const from = edges[i]!
    const to = edges[i + 1]!
    let cat: Category = 'other'
    for (const p of parts) {
      if (p.from <= from && p.to >= to && PRIORITY[p.cat] > PRIORITY[cat]) cat = p.cat
    }
    out[cat] += to - from
  }

  return out
}

export function percentages(b: Breakdown): Breakdown {
  const total = b.model + b.tool + b.wait + b.other
  if (total <= 0) return { model: 0, tool: 0, wait: 0, other: 0 }
  return {
    model: Math.round((b.model / total) * 100),
    tool: Math.round((b.tool / total) * 100),
    wait: Math.round((b.wait / total) * 100),
    other: Math.round((b.other / total) * 100),
  }
}

function dur(s: Span, now: number): number {
  return spanEnd(s, now) - s.start
}

/** The model requests of the main loop, oldest first, with the tool calls each asked for. */
export function steps(turn: Turn, now: number): { model: Span; tools: Span[] }[] {
  const main = turn.spans.filter(s => s.agentId === undefined)
  const models = main.filter(s => s.kind === 'model').sort((a, b) => a.start - b.start)
  return models.map((model, i) => {
    const from = spanEnd(model, now)
    const until = models[i + 1]?.start ?? Number.POSITIVE_INFINITY
    const tools = main.filter(s => s.kind === 'tool' && s.start >= from - 1 && s.start < until)
    return { model, tools }
  })
}

/**
 * What a turn's profile says to do about it, the biggest saving first.
 * `history` is the session's earlier turns, for patterns across turns.
 */
export function insights(turn: Turn, history: readonly Turn[], now: number): Insight[] {
  const total = turn.durationMs ?? now
  const tools = turn.spans.filter(s => s.kind === 'tool')
  const found: Insight[] = []

  // Approvals: time the person spent at permission prompts.
  const asked = tools.filter(s => s.isAsked)
  const waited = asked.reduce((sum, s) => sum + (s.waitMs ?? 0), 0)
  if (asked.length > 0 && waited >= 3000) {
    const byRule = new Map<string, number>()
    for (const s of asked) {
      const key = s.rule ?? s.name
      byRule.set(key, (byRule.get(key) ?? 0) + 1)
    }
    const [rule, count] = [...byRule].sort((a, b) => b[1] - a[1])[0]!
    const before = history.reduce(
      (n, t) => n + t.spans.filter(s => s.isAsked && (s.rule ?? s.name) === rule).length,
      0,
    )
    const prompts = asked.length === 1 ? '1 approval' : `${asked.length} approvals`
    const hasRule = asked.some(s => s.rule === rule)
    const seen = before > 0 ? ` Asked ${before + count}× this session.` : ''
    const which = count === asked.length ? (count === 1 ? 'it' : 'them all') : `${count} of them`
    found.push({
      kind: 'approvals',
      text: hasRule
        ? `${prompts} cost ${fmtMs(waited)}. Allowing ${rule} would skip ${which}.${seen}`
        : `${prompts} cost ${fmtMs(waited)} (${rule}).${seen}`,
      savableMs: waited,
      ...(hasRule ? { rule } : {}),
    })
  }

  // Retries: the same call failing again and again.
  const failures = new Map<string, Span[]>()
  for (const s of tools) {
    if (!s.isError) continue
    const key = `${s.name}\u0000${s.detail}`
    failures.set(key, [...(failures.get(key) ?? []), s])
  }
  const worst = [...failures.values()].sort((a, b) => b.length - a.length)[0]
  if (worst !== undefined && worst.length >= 2) {
    const spent = worst.reduce((sum, s) => sum + dur(s, now), 0)
    const what = worst[0]!.detail ? `${worst[0]!.name} \`${worst[0]!.detail}\`` : worst[0]!.name
    found.push({
      kind: 'retries',
      text: `${what} failed ${worst.length}× (${fmtMs(spent)}): a retry loop, not progress.`,
      savableMs: spent - dur(worst[0]!, now),
    })
  }

  // One call that was most of the turn.
  const longest = tools
    .filter(s => s.agentId === undefined)
    .sort((a, b) => dur(b, now) - dur(a, now))[0]
  if (longest !== undefined && total > 0) {
    const ran = longest.execMs ?? dur(longest, now) - (longest.waitMs ?? 0)
    if (ran >= 10_000 && ran / total >= 0.4) {
      const what = longest.detail ? `${longest.name} \`${longest.detail}\`` : longest.name
      found.push({
        kind: 'dominant',
        text: `${what} ran ${fmtMs(ran)}, ${Math.round((ran / total) * 100)}% of the turn.`,
      })
    }
  }

  // Slow first tokens: the model, not the tools, is the wait.
  const models = turn.spans.filter(s => s.kind === 'model' && s.firstTokenMs !== undefined)
  if (models.length >= 3) {
    const avg = models.reduce((sum, s) => sum + s.firstTokenMs!, 0) / models.length
    if (avg >= 4000) {
      const effort = models.find(s => s.effort !== undefined)?.effort
      const hint =
        effort === 'high' || effort === 'xhigh' || effort === 'max'
          ? ` Effort is ${effort}; a lower effort answers sooner.`
          : ''
      found.push({
        kind: 'first-token',
        text: `${models.length} model requests waited ${fmtMs(avg)} on average for a first token.${hint}`,
      })
    }
  }

  // Serial reads: one read per model round-trip.
  const all = steps(turn, now)
  let run: typeof all = []
  let best: typeof all = []
  for (const step of all) {
    const isSingleRead = step.tools.length === 1 && READ_ONLY.has(step.tools[0]!.name)
    run = isSingleRead ? [...run, step] : []
    if (run.length > best.length) best = run
  }
  if (best.length >= 4) {
    const saved = best.slice(1).reduce((sum, s) => sum + dur(s.model, now), 0)
    found.push({
      kind: 'serial-reads',
      text: `${best.length} reads went out one per model request; reading them in parallel saves ~${best.length - 1} round-trips (${fmtMs(saved)}).`,
      savableMs: saved,
    })
  }

  return found.sort((a, b) => (b.savableMs ?? 0) - (a.savableMs ?? 0))
}

/** Packs spans into lanes so that no two in one lane overlap. */
export function lanes(spans: readonly Span[], now: number): Map<string, number> {
  const ends: number[] = []
  const out = new Map<string, number>()
  for (const s of [...spans].sort((a, b) => a.start - b.start)) {
    let lane = ends.findIndex(end => end <= s.start)
    if (lane === -1) lane = ends.length
    ends[lane] = spanEnd(s, now)
    out.set(s.id, lane)
  }
  return out
}

type TraceEvent = Record<string, unknown>

/**
 * The turn as a Chrome Trace Event file: open it in https://ui.perfetto.dev
 * or chrome://tracing. One process per loop, the model on thread 1 and
 * parallel tool calls on threads of their own.
 */
export function toTrace(turn: Turn, now: number): { traceEvents: TraceEvent[]; otherData: Record<string, unknown> } {
  const events: TraceEvent[] = []
  const loops = [...new Set(turn.spans.map(s => s.agentId ?? ''))]
  const us = (ms: number) => Math.round(ms * 1000)

  loops.forEach((loop, i) => {
    const pid = i + 1
    const spans = turn.spans.filter(s => (s.agentId ?? '') === loop)
    events.push({ ph: 'M', name: 'process_name', pid, args: { name: loop === '' ? 'main loop' : `subagent ${loop}` } })
    events.push({ ph: 'M', name: 'thread_name', pid, tid: 1, args: { name: 'model' } })
    const toolLanes = lanes(spans.filter(s => s.kind === 'tool'), now)
    for (const lane of new Set(toolLanes.values())) {
      events.push({ ph: 'M', name: 'thread_name', pid, tid: lane + 2, args: { name: `tools ${lane + 1}` } })
    }

    for (const s of spans) {
      const tid = s.kind === 'model' ? 1 : toolLanes.get(s.id)! + 2
      const end = spanEnd(s, now)
      events.push({
        ph: 'X',
        name: s.detail ? `${s.name}: ${s.detail}` : s.name,
        cat: s.kind,
        pid,
        tid,
        ts: us(s.start),
        dur: us(end - s.start),
        args: {
          ...(s.execMs !== undefined ? { execMs: s.execMs } : {}),
          ...(s.waitMs !== undefined ? { approvalWaitMs: s.waitMs } : {}),
          ...(s.rule !== undefined ? { suggestedRule: s.rule } : {}),
          ...(s.firstTokenMs !== undefined ? { firstTokenMs: s.firstTokenMs } : {}),
          ...(s.outTokens !== undefined ? { outputTokens: s.outTokens } : {}),
          ...(s.effort !== undefined ? { effort: s.effort } : {}),
          ...(s.isError ? { isError: true } : {}),
        },
      })
      if (s.waitMs !== undefined && s.waitMs > 0) {
        events.push({ ph: 'X', name: 'waiting for approval', cat: 'wait', pid, tid, ts: us(s.start), dur: us(Math.min(s.waitMs, end - s.start)) })
      }
      if (s.firstTokenMs !== undefined) {
        events.push({ ph: 'X', name: 'time to first token', cat: 'model', pid, tid, ts: us(s.start), dur: us(Math.min(s.firstTokenMs, end - s.start)) })
      }
    }
  })

  return {
    traceEvents: events,
    otherData: {
      turnId: turn.id,
      prompt: turn.prompt,
      startedAt: new Date(turn.startedAt).toISOString(),
      durationMs: turn.durationMs ?? now,
      generator: 'turn-profiler',
    },
  }
}

const BARS = '▁▂▃▄▅▆▇█'

export function sparkline(values: readonly number[]): string {
  const max = Math.max(...values, 1)
  return values.map(v => BARS[Math.min(7, Math.floor((v / max) * 7.999))]).join('')
}

export type ToolRow = { name: string; calls: number; totalMs: number; maxMs: number; failed: number }

export function toolTable(turn: Turn, now: number): ToolRow[] {
  const rows = new Map<string, ToolRow>()
  for (const s of turn.spans) {
    if (s.kind !== 'tool') continue
    const row = rows.get(s.name) ?? { name: s.name, calls: 0, totalMs: 0, maxMs: 0, failed: 0 }
    const d = dur(s, now)
    rows.set(s.name, {
      ...row,
      calls: row.calls + 1,
      totalMs: row.totalMs + d,
      maxMs: Math.max(row.maxMs, d),
      failed: row.failed + (s.isError ? 1 : 0),
    })
  }
  return [...rows.values()].sort((a, b) => b.totalMs - a.totalMs)
}

/** A plain-text report of recent turns, for the model's own tool. */
export function report(turns: readonly Turn[], now: number): string {
  if (turns.length === 0) return 'No turn has been profiled yet in this session.'
  return turns
    .map(t => {
      const b = breakdown(t, now)
      const p = percentages(b)
      const lines = [
        `Turn "${t.prompt}" took ${fmtMs(t.durationMs ?? now)}${t.isAborted ? ' (interrupted)' : ''}: model ${p.model}%, tools ${p.tool}%, waiting for approval ${p.wait}%, other ${p.other}%.`,
      ]
      const top = toolTable(t, now).slice(0, 4)
      if (top.length > 0) {
        lines.push(`Tools: ${top.map(r => `${r.name} ×${r.calls} ${fmtMs(r.totalMs)}${r.failed ? ` (${r.failed} failed)` : ''}`).join(', ')}.`)
      }
      for (const i of insights(t, [], now)) lines.push(`- ${i.text}`)
      return lines.join('\n')
    })
    .join('\n\n')
}

