import type { Elements } from 'claude-code'

import type { Breakdown, Category, Insight, Span, Turn } from '../types'
import { fmtMs, percentages, spanEnd, toolTable } from './model'

type Els = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button'>

const ORDER: readonly Category[] = ['model', 'tool', 'wait', 'other']
const NAME: Record<Category, string> = { model: 'model', tool: 'tools', wait: 'approvals', other: 'other' }
/** Theme keys, so the colors follow the person's theme. */
const THEME: Record<Category | 'error', string> = {
  model: 'merged',
  tool: 'suggestion',
  wait: 'warning',
  other: 'inactive',
  error: 'error',
}

/** Splits `width` cells among the categories, largest remainder first. */
function cells(b: Breakdown, width: number): Record<Category, number> {
  const total = ORDER.reduce((sum, c) => sum + b[c], 0)
  const out: Record<Category, number> = { model: 0, tool: 0, wait: 0, other: 0 }
  if (total <= 0) return out
  const exact = ORDER.map(c => ({ c, v: (b[c] / total) * width }))
  for (const { c, v } of exact) out[c] = Math.floor(v)
  let left = width - ORDER.reduce((sum, c) => sum + out[c], 0)
  for (const { c } of [...exact].sort((x, y) => (y.v % 1) - (x.v % 1))) {
    if (left-- <= 0) break
    out[c] += 1
  }
  return out
}

function StackBar({ Text }: Els, b: Breakdown, width: number) {
  const n = cells(b, width)
  return (
    <Text>
      {ORDER.filter(c => n[c] > 0).map(c => (
        <Text color={THEME[c]}>{'█'.repeat(n[c])}</Text>
      ))}
    </Text>
  )
}

function Legend({ Text }: Els, b: Breakdown, isShort: boolean) {
  const p = percentages(b)
  const shown = ORDER.filter(c => p[c] > 0 && (c !== 'other' || !isShort))
  return (
    <Text>
      {shown.map((c, i) => (
        <Text>
          {i > 0 ? ' · ' : ''}
          <Text color={THEME[c]}>{NAME[c]}</Text>
          <Text dimColor> {p[c]}%</Text>
        </Text>
      ))}
    </Text>
  )
}

export type BandData = {
  turn: Turn
  breakdown: Breakdown
  insight: Insight | undefined
  spark: string
  columns: number
  onOpen: () => void
  onHide: () => void
  onCopy: (rule: string) => void
}

export function BandView(els: Els, d: BandData) {
  const { Box, Text, Button } = els
  const isNarrow = d.columns < 80
  return (
    <Box flexDirection="column">
      <Box flexDirection="row" gap={1}>
        <Text bold>⏱ {fmtMs(d.turn.durationMs ?? 0)}</Text>
        {StackBar(els, d.breakdown, isNarrow ? 10 : 16)}
        {Legend(els, d.breakdown, isNarrow)}
        {!isNarrow && d.spark.length > 1 && <Text dimColor>{d.spark}</Text>}
        <Button key="open" label="Profile" onPress={d.onOpen} />
        <Button key="hide" label="Hide" onPress={d.onHide} />
      </Box>
      {d.insight !== undefined && (
        <Box flexDirection="row" gap={1}>
          <Text dimColor wrap="truncate-end">
            ↳ {d.insight.text}
          </Text>
          {d.insight.rule !== undefined && (
            <Button key="copy-rule" label="Copy rule" onPress={() => d.onCopy(d.insight!.rule!)} />
          )}
        </Box>
      )}
    </Box>
  )
}

/** The spans worth drawing in `rows` rows: every one, or the longest in time order. */
export function pickRows(spans: readonly Span[], rows: number, now: number): { shown: Span[]; hidden: number } {
  const sorted = [...spans].sort((a, b) => a.start - b.start)
  if (sorted.length <= rows) return { shown: sorted, hidden: 0 }
  const keep = new Set(
    [...sorted]
      .sort((a, b) => spanEnd(b, now) - b.start - (spanEnd(a, now) - a.start))
      .slice(0, rows)
      .map(s => s.id),
  )
  return { shown: sorted.filter(s => keep.has(s.id)), hidden: sorted.length - keep.size }
}

function label(s: Span): string {
  const who = s.agentId !== undefined ? '↳ ' : ''
  if (s.kind === 'model') return `${who}model ${s.detail}`
  return `${who}${s.name}${s.detail ? ` ${s.detail}` : ''}`
}

function cut(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, Math.max(1, max - 1))}…` : text
}

function tooltip(s: Span, now: number): string {
  const total = spanEnd(s, now) - s.start
  const parts = [`${s.kind === 'model' ? `model request · ${s.name}` : s.name}${s.detail ? ` · ${s.detail}` : ''}`]
  parts.push(`${fmtMs(total)}${s.end === undefined ? ' so far' : ''}`)
  if (s.waitMs) parts.push(`${fmtMs(s.waitMs)} waiting for approval`)
  if (s.execMs !== undefined) parts.push(`${fmtMs(s.execMs)} running`)
  if (s.firstTokenMs !== undefined) parts.push(`${fmtMs(s.firstTokenMs)} to first token`)
  if (s.outTokens !== undefined) parts.push(`${s.outTokens} output tokens`)
  if (s.rule) parts.push(`suggested rule: ${s.rule}`)
  if (s.isError) parts.push('failed')
  return parts.join('\n')
}

/** Each cell of a span's bar: what it was doing then. */
function barCells(s: Span, total: number, width: number, now: number): (Category | 'error' | 'first' | null)[] {
  const row: (Category | 'error' | 'first' | null)[] = Array(width).fill(null)
  if (total <= 0) return row
  const at = (t: number) => Math.min(width - 1, Math.max(0, Math.floor((t / total) * width)))
  const from = at(s.start)
  const to = Math.max(from, at(spanEnd(s, now) - 1))
  const wait = s.waitMs ? at(s.start + s.waitMs) : -1
  const first = s.firstTokenMs !== undefined ? at(s.start + s.firstTokenMs) : -1
  for (let i = from; i <= to; i++) {
    if (s.kind === 'model') row[i] = i < first ? 'first' : 'model'
    else if (i < wait) row[i] = 'wait'
    else row[i] = s.isError ? 'error' : 'tool'
  }
  return row
}

export function WaterfallText(els: Els, spans: readonly Span[], total: number, now: number, columns: number, rows: number) {
  const { Box, Text } = els
  const { shown, hidden } = pickRows(spans, rows, now)
  const labelWidth = Math.min(28, Math.max(12, Math.floor(columns * 0.3)))
  const barWidth = Math.max(10, columns - labelWidth - 9)
  return (
    <Box flexDirection="column">
      {shown.map(s => {
        const row = barCells(s, total, barWidth, now)
        const runs: { kind: (typeof row)[number]; n: number }[] = []
        for (const kind of row) {
          const last = runs[runs.length - 1]
          if (last !== undefined && last.kind === kind) last.n += 1
          else runs.push({ kind, n: 1 })
        }
        return (
          <Box flexDirection="row">
            <Box width={labelWidth}>
              <Text dimColor={s.kind === 'model'} wrap="truncate-end">
                {cut(label(s), labelWidth - 1)}
              </Text>
            </Box>
            <Text>
              {runs.map(r =>
                r.kind === null ? (
                  ' '.repeat(r.n)
                ) : (
                  <Text color={THEME[r.kind === 'first' ? 'model' : r.kind]} dimColor={r.kind === 'first'}>
                    {(r.kind === 'first' ? '░' : '█').repeat(r.n)}
                  </Text>
                ),
              )}
            </Text>
            <Text dimColor>
              {' '}
              {fmtMs(spanEnd(s, now) - s.start).padStart(6)}
              {s.end === undefined ? '…' : ''}
            </Text>
          </Box>
        )
      })}
      {hidden > 0 && <Text dimColor>+{hidden} shorter spans not drawn</Text>}
    </Box>
  )
}

function esc(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

const STEPS = [100, 200, 500, 1000, 2000, 5000, 10_000, 15_000, 30_000, 60_000, 120_000, 300_000, 600_000, 1_800_000]

/** A waterfall as an SVG document, each bar with a hover tooltip. */
export function waterfallSvg(spans: readonly Span[], total: number, now: number, width: number, rows: number): { source: string; height: number; hidden: number } {
  const { shown, hidden } = pickRows(spans, rows, now)
  const labelWidth = Math.round(Math.min(260, width * 0.34))
  const durWidth = 58
  const barX = labelWidth + 8
  const barWidth = Math.max(40, width - barX - durWidth - 6)
  const rowHeight = 20
  const top = 22
  const height = top + shown.length * rowHeight + 6
  const span = Math.max(total, 1)
  const x = (t: number) => barX + (Math.min(Math.max(t, 0), span) / span) * barWidth
  const step = STEPS.find(s => span / s <= 6) ?? 3_600_000
  const out: string[] = []

  out.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`,
    '<style>',
    'text{font:11px -apple-system,BlinkMacSystemFont,"Segoe UI",system-ui,sans-serif;fill:#5f6368}',
    '.v{font-variant-numeric:tabular-nums}.grid{stroke:#8b929a;stroke-opacity:.22}',
    '.row:hover .bg{fill-opacity:.12}.bg{fill:#8b929a;fill-opacity:0}',
    '@media (prefers-color-scheme:dark){text{fill:#bdc1c6}}',
    '</style>',
  )
  for (let t = 0; t <= span + 1; t += step) {
    out.push(`<line class="grid" x1="${x(t)}" x2="${x(t)}" y1="${top - 4}" y2="${height - 4}"/>`)
    out.push(`<text class="v" x="${x(t)}" y="12" text-anchor="${t === 0 ? 'start' : 'middle'}">${t === 0 ? '0' : fmtMs(t)}</text>`)
  }
  shown.forEach((s, i) => {
    const y = top + i * rowHeight
    const end = spanEnd(s, now)
    const x0 = x(s.start)
    const w = Math.max(2, x(end) - x0)
    const running = s.end === undefined ? ' fill-opacity="0.55"' : ''
    out.push(`<g class="row"><title>${esc(tooltip(s, now))}</title>`)
    out.push(`<rect class="bg" x="0" y="${y}" width="${width}" height="${rowHeight}"/>`)
    out.push(`<text x="4" y="${y + 14}">${esc(cut(label(s), Math.floor(labelWidth / 6.3)))}</text>`)
    if (s.kind === 'model') {
      out.push(`<rect x="${x0}" y="${y + 4}" width="${w}" height="12" rx="2" fill="#8b5cf6"${running}/>`)
      if (s.firstTokenMs !== undefined) {
        const fw = Math.min(w, x(s.start + s.firstTokenMs) - x0)
        out.push(`<rect x="${x0}" y="${y + 4}" width="${fw}" height="12" rx="2" fill="#c4b5fd"/>`)
      }
    } else {
      out.push(`<rect x="${x0}" y="${y + 4}" width="${w}" height="12" rx="2" fill="${s.isError ? '#ef4444' : '#3b82f6'}"${running}/>`)
      if (s.waitMs) {
        const ww = Math.min(w, x(s.start + s.waitMs) - x0)
        out.push(`<rect x="${x0}" y="${y + 4}" width="${ww}" height="12" rx="2" fill="#f59e0b"/>`)
      }
    }
    out.push(`<text class="v" x="${width - 4}" y="${y + 14}" text-anchor="end">${fmtMs(end - s.start)}${s.end === undefined ? '…' : ''}</text></g>`)
  })
  out.push('</svg>')
  return { source: out.join(''), height, hidden }
}

export type PaneData = {
  turn: Turn | null
  isLive: boolean
  position: { index: number; count: number }
  breakdown: Breakdown
  insights: readonly Insight[]
  now: number
  columns: number
  isBandHidden: boolean
  onPrev: () => void
  onNext: () => void
  onLatest: () => void
  onExport: () => void
  onToggleBand: () => void
  onCopy: (rule: string) => void
}

export function PaneHead(els: Els, d: PaneData) {
  const { Box, Text, Button } = els
  const t = d.turn!
  const total = t.durationMs ?? d.now
  const models = t.spans.filter(s => s.kind === 'model').length
  const tools = t.spans.filter(s => s.kind === 'tool').length
  const out = t.spans.reduce((sum, s) => sum + (s.outTokens ?? 0), 0)
  return (
    <Box flexDirection="column" gap={1}>
      <Box flexDirection="row" gap={1}>
        <Text bold color={d.isLive ? 'success' : undefined}>
          {d.isLive ? '● live' : `turn ${d.position.index + 1}/${d.position.count}`}
        </Text>
        <Text dimColor wrap="truncate-end">
          “{t.prompt}”
        </Text>
        <Button key="prev" label="‹ Prev" onPress={d.onPrev} />
        <Button key="next" label="Next ›" onPress={d.onNext} />
        <Button key="latest" label="Latest" onPress={d.onLatest} />
      </Box>
      <Box flexDirection="column">
        <Text>
          <Text bold>{fmtMs(total)}</Text>
          {d.isLive ? <Text dimColor> so far</Text> : ''}
          {t.isAborted ? <Text color="warning"> interrupted</Text> : ''}
          <Text dimColor>
            {' '}
            · {models} model request{models === 1 ? '' : 's'} · {tools} tool call{tools === 1 ? '' : 's'}
            {out > 0 ? ` · ${out.toLocaleString('en-US')} output tokens` : ''}
            {t.droppedSpans ? ` · ${t.droppedSpans} spans over the cap` : ''}
          </Text>
        </Text>
        <Box flexDirection="row" gap={1}>
          {StackBar(els, d.breakdown, Math.min(32, Math.max(12, Math.floor(d.columns / 3))))}
          {Legend(els, d.breakdown, false)}
        </Box>
      </Box>
      {d.insights.length > 0 && (
        <Box flexDirection="column">
          {d.insights.slice(0, 4).map((i, n) => (
            <Box flexDirection="row" gap={1}>
              <Text color="warning">▲</Text>
              <Text wrap="wrap">{i.text}</Text>
              {i.rule !== undefined && (
                <Button key={`copy-${n}`} label="Copy rule" onPress={() => d.onCopy(i.rule!)} />
              )}
            </Box>
          ))}
        </Box>
      )}
    </Box>
  )
}

export function PaneFoot(els: Els, d: PaneData) {
  const { Box, Text, Button } = els
  const rows = toolTable(d.turn!, d.now).slice(0, 6)
  return (
    <Box flexDirection="column" gap={1}>
      {rows.length > 0 && (
        <Box flexDirection="column">
          <Box flexDirection="row">
            <Box width={16}><Text dimColor>tool</Text></Box>
            <Box width={8}><Text dimColor>calls</Text></Box>
            <Box width={10}><Text dimColor>total</Text></Box>
            <Box width={10}><Text dimColor>slowest</Text></Box>
            <Text dimColor>failed</Text>
          </Box>
          {rows.map(r => (
            <Box flexDirection="row">
              <Box width={16}><Text wrap="truncate-end">{r.name}</Text></Box>
              <Box width={8}><Text>{r.calls}</Text></Box>
              <Box width={10}><Text>{fmtMs(r.totalMs)}</Text></Box>
              <Box width={10}><Text>{fmtMs(r.maxMs)}</Text></Box>
              <Text color={r.failed > 0 ? 'error' : undefined} dimColor={r.failed === 0}>{r.failed}</Text>
            </Box>
          ))}
        </Box>
      )}
      <Box flexDirection="row" gap={1}>
        <Button key="export" label="Export trace" onPress={d.onExport} />
        <Button key="band" label={d.isBandHidden ? 'Show band' : 'Hide band'} onPress={d.onToggleBand} />
        <Text dimColor>Export opens in ui.perfetto.dev</Text>
      </Box>
    </Box>
  )
}

export function Legendary(els: Els) {
  const { Text } = els
  return (
    <Text dimColor>
      <Text color={THEME.model}>█</Text> model <Text color={THEME.model} dimColor>░</Text> to first token{' '}
      <Text color={THEME.tool}>█</Text> tool <Text color={THEME.wait}>█</Text> approval <Text color={THEME.error}>█</Text> failed
    </Text>
  )
}

export function Empty({ Text }: Els) {
  return <Text dimColor>No turn profiled yet. Send a prompt and this pane fills in while Claude works.</Text>
}

