/** One timed piece of a turn: a model request or a tool call. */
export type Span = {
  /** The tool_use_id for a tool call; `m:<loop>:<step>` for a model request. */
  id: string
  kind: 'model' | 'tool'
  /** The tool's name, or the model's. */
  name: string
  /** A one-line summary: the command, the file, the pattern. */
  detail: string
  /** The subagent's loop it ran in; absent on the main loop. */
  agentId?: string
  /** Milliseconds from the turn's start. */
  start: number
  /** Milliseconds from the turn's start; absent while it runs. */
  end?: number
  /** Tool calls: time the tool itself ran (PostToolUse's duration_ms). */
  execMs?: number
  /** Tool calls: time spent waiting on a permission prompt. */
  waitMs?: number
  /** Tool calls: whether the person was asked to approve it. */
  isAsked?: boolean
  /** Tool calls: the allow rule the engine suggested at the prompt. */
  rule?: string
  /** Model requests: time to the first streamed chunk. */
  firstTokenMs?: number
  /** Model requests: the effort level the request asked for. */
  effort?: string
  /** Model requests: output tokens. */
  outTokens?: number
  isError?: boolean
}

export type Turn = {
  id: string
  /** The prompt, cut to one line. */
  prompt: string
  /** Epoch milliseconds. */
  startedAt: number
  /** Wall-clock length; absent while the turn runs. */
  durationMs?: number
  isAborted?: boolean
  spans: Span[]
  /** Spans left out once a turn passes the cap. */
  droppedSpans?: number
}

export type Category = 'model' | 'tool' | 'wait' | 'other'

export type Breakdown = Record<Category, number>

export type Insight = {
  kind: 'approvals' | 'retries' | 'dominant' | 'first-token' | 'serial-reads'
  /** One line, already worded for the person. */
  text: string
  /** Milliseconds the insight says could be saved, when it can say. */
  savableMs?: number
  /** An allow rule to copy, for an approvals insight. */
  rule?: string
}

declare module 'claude-code' {
  interface PluginState {
    'turn-profiler': {
      /** The main loop's turn while it runs. */
      live: Turn | null
      /** Finished turns, oldest first, the newest 40 kept. */
      turns: Turn[]
      /** The turn the pane shows: its id, or null for the newest. */
      viewing: string | null
      isBandHidden: boolean
      /** Bumped every second while a turn runs, so running spans redraw. */
      tick: number
    }
  }
}
